INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "兴平公主", "aliases": ["興平公主", "齐国公主", "齊國公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：兴平公主，李嗣源之女、赵延寿妻子。", "biography": null, "status": "draft", "id": "972f102f-da22-55ba-b552-95861efd9735"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "赵可封", "aliases": ["趙可封"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐太府卿。938年九月建议徐诰恢复李姓并设立唐朝宗庙。此段只记建议，未记已执行；生卒年未载。", "biography": null, "status": "draft", "id": "918e7031-0a99-5fe1-a78a-bbefc6424ca0"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "刘处让", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘处让。", "biography": null, "status": "draft", "id": "7607f037-c9b6-5f79-b064-81fcfd4ee40d"}, {"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：范延光。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "李式（范延光节度副使）", "aliases": ["李式"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "范延光的节度副使。938年范延光在考虑归降时，向他表示相信石敬瑭不杀自己的承诺。生卒年未载。", "biography": null, "status": "draft", "id": "c77924ab-61e5-52d0-a54d-2fdd6af97658"}, {"name": "孙汉威", "aliases": ["孫漢威"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "范延光的将佐。938年九月获授地方官职，《旧五代史》记为陇州防御使，并列此前贝州刺史职衔。生卒年未载。", "biography": null, "status": "draft", "id": "37b08f2c-cef5-5ce1-9906-43bb10a1b270"}, {"name": "薛霸", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "范延光的将佐。938年九月获授地方官职，《旧五代史》记为卫州刺史，并列此前天雄军三城都巡检使职衔。生卒年未载。", "biography": null, "status": "draft", "id": "13f72928-c1f1-55f2-add6-3d02ba0dbbb3"}, {"name": "李彦珣", "aliases": ["李彥珣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李彦珣，退事舍人、赴东川使者。", "biography": null, "status": "draft", "id": "724412dc-62b3-5aee-8d78-cb03e194c6cb"}, {"name": "张从宾", "aliases": ["張從賓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：张从宾，侍卫步军都指挥使、忠正节度使。", "biography": null, "status": "draft", "id": "9a3c8e19-d709-5a20-b9dd-ef00849d161d"}, {"name": "李彦珣母（姓名未详）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李彦珣的母亲，姓名未载。《资治通鉴》《旧五代史》记载，广晋被围时杨光远将她带到城下招降李彦珣，她被李彦珣射杀；具体年月未载。", "biography": null, "status": "draft", "id": "868c0704-1f53-5af4-8d95-0187169a78e2"}, {"name": "王权", "aliases": ["王權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：王权。", "biography": null, "status": "draft", "id": "9300dc45-742f-5104-bd01-edb3c43ed82f"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

